sys_script_include.script:
var PatientTimelineService = Class.create();

PatientTimelineService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Patient Timeline record exists.
     *
     * @param {String} timelineSysId
     * @return {Boolean}
     */
    timelineExists: function(timelineSysId) {

        if (this.validationUtils.isEmpty(timelineSysId)) {
            return false;
        }

        var timeline = new GlideRecord(
            'x_2130921_caresy_0_patient_timeline'
        );

        if (!timeline.isValid()) {
            gs.error(
                'PatientTimelineService: Patient Timeline table is invalid.'
            );
            return false;
        }

        return timeline.get(timelineSysId);
    },

    /**
     * Retrieve a Patient Timeline record.
     *
     * @param {String} timelineSysId
     * @return {GlideRecord|null}
     */
    getTimeline: function(timelineSysId) {

        if (this.validationUtils.isEmpty(timelineSysId)) {
            return null;
        }

        var timeline = new GlideRecord(
            'x_2130921_caresy_0_patient_timeline'
        );

        if (!timeline.isValid()) {
            gs.error(
                'PatientTimelineService: Patient Timeline table is invalid.'
            );
            return null;
        }

        if (timeline.get(timelineSysId)) {
            return timeline;
        }

        return null;
    },

    /**
     * Check whether a Patient Timeline record is active.
     *
     * @param {String} timelineSysId
     * @return {Boolean}
     */
    isTimelineActive: function(timelineSysId) {

        var timeline = this.getTimeline(timelineSysId);

        if (!timeline) {
            return false;
        }

        return timeline.getValue('active') == '1';
    },

    type: 'PatientTimelineService'
};
